# Série d'exercices de fin de chapitre — Physique 6C.
# k = "book" : exercice du manuel (src = page et numéro) ; "extra" : exercice du même type ; "int" : situation d'intégration.
SERIES = {}

SERIES["Physique – Chapitre I : Mouvements rectilignes et circulaires"] = [
 {"k": "book", "src": "p. 31, ex. 1", "q": "Un signal radar revient à son point d’émission 4 ms après avoir été émis (c = 3 × 10⁸ m/s). À quelle distance se trouve l’obstacle ?",
  "a": "Le signal fait l’aller-retour : d = c × t/2 = 3 × 10⁸ × 4 × 10⁻³/2 = 6,0 × 10⁵ m = 600 km."},
 {"k": "book", "src": "p. 32, ex. 9", "q": "Un mobile en m.r.u.v. est à x₀ = 1 m à t = 0, à x₁ = 0 à t = 1 s et à x₂ = −7 m à t = 2 s. Déterminer a et v₀, puis les équations horaires.",
  "a": "x = ½at² + v₀t + 1. t = 1 : ½a + v₀ = −1 ; t = 2 : 2a + 2v₀ = −8. D’où a = −6 m/s² et v₀ = 2 m/s. x(t) = −3t² + 2t + 1 ; v(t) = −6t + 2. Le mouvement est retardé jusqu’à t = 1/3 s puis accéléré dans le sens négatif."},
 {"k": "book", "src": "p. 32", "q": "Un mobile tombe sans vitesse initiale ; dans un repère vertical orienté vers le haut, x = −4t² + 4. 1) Position à t = 0. 2) Vitesse en fonction de t. 3) Positions et vitesses à t = 1 s et t = 2 s.",
  "a": "1) x = 4 m.\n2) v = −8t (m/s).\n3) t = 1 s : x = 0, v = −8 m/s ; t = 2 s : x = −12 m, v = −16 m/s."},
 {"k": "book", "src": "p. 33", "q": "x = t²/2 et y = 1 − t². 1) Équation de la trajectoire. 2) Vecteurs vitesse et accélération. 3) Valeurs à t = 0,5 s.",
  "a": "1) t² = 2x ⇒ y = 1 − 2x (demi-droite, x ≥ 0).\n2) v⃗(t ; −2t) ; a⃗(1 ; −2) constant : mouvement rectiligne uniformément accéléré.\n3) v = 0,5√5 ≈ 1,12 m/s ; a = √5 ≈ 2,24 m/s²."},
 {"k": "book", "src": "p. 33", "q": "Une locomotive démarre avec a = 2 m/s² jusqu’à 72 km/h, puis garde cette vitesse 30 s. 1) Distance totale. 2) Elle freine ensuite avec une décélération de 2 m/s² : durée et distance de freinage.",
  "a": "1) 20 m/s atteints en 10 s, sur 100 m ; puis 20 × 30 = 600 m : total 700 m.\n2) Durée 20/2 = 10 s ; distance v²/(2a) = 100 m (elle s’arrête exactement en 100 m)."},
 {"k": "book", "src": "p. 33", "q": "Un mobile passe aux abscisses −4 ; −2,5 ; 0 ; 3,5 ; 8 ; 13,5 ; 20 cm aux instants 0 ; 40 ; … ; 240 ms. 1) Nature du mouvement et accélération. 2) Vitesses en B à F. 3) Vitesses en A et G. 4) Équation horaire.",
  "a": "1) Les distances successives augmentent de 1 cm à chaque intervalle : m.r.u.v., a = 0,01/0,04² = 6,25 m/s².\n2) v = distance sur deux intervalles/0,08 s : vB = 0,50 ; vC = 0,75 ; vD = 1,00 ; vE = 1,25 ; vF = 1,50 m/s.\n3) vA = 0,25 m/s ; vG = 1,75 m/s.\n4) x(t) = 3,125t² + 0,25t − 0,04 (m, s)."},
 {"k": "book", "src": "p. 33", "q": "Une auto à l’arrêt démarre au vert avec a = 2 m/s² pendant 8 s puis roule à vitesse constante ; au démarrage un camion la dépasse à 12 m/s. Quand et où l’auto rattrape-t-elle le camion ?",
  "a": "Auto : x = t² pour t ≤ 8 s (x = 64 m, v = 16 m/s à 8 s), puis x = 64 + 16(t − 8). Camion : x = 12t. Avant 8 s, t² = 12t donnerait t = 12 s > 8 s, donc on utilise la 2e phase : 64 + 16(t − 8) = 12t ⇒ t = 16 s, à 192 m du feu."},
 {"k": "book", "src": "p. 33", "q": "Un mobile a pour vitesse v⃗ = 2i⃗ + (6t − 12)j⃗ et part de O à t = 0. 1) Vecteur position et accélération. 2) Quand la vitesse fait-elle 45° avec i⃗ ? 3) À t = 2 s : position, accélérations tangentielle et normale, rayon de courbure.",
  "a": "1) OM⃗ = 2t i⃗ + (3t² − 12t) j⃗ ; a⃗ = 6j⃗.\n2) 6t − 12 = ±2 ⇒ t = 5/3 s ou 7/3 s.\n3) M(4 ; −12) ; v⃗ = 2i⃗ ⊥ a⃗ : aₜ = 0, aₙ = 6 m/s² ; R = v²/aₙ = 4/6 ≈ 0,67 m."},
 {"k": "int", "src": "", "q": "Une moto roule à 90 km/h sur une route. Le conducteur voit un obstacle à 60 m ; son temps de réaction est de 0,8 s, puis il freine avec une décélération de 6 m/s².\n1) Distance parcourue pendant le temps de réaction.\n2) Distance de freinage.\n3) Évite-t-il l’obstacle ? Et à 110 km/h ?",
  "a": "1) 25 × 0,8 = 20 m.\n2) v²/(2a) = 625/12 ≈ 52 m.\n3) Distance d’arrêt ≈ 72 m > 60 m : il heurte l’obstacle. À 110 km/h (30,6 m/s) : 24,4 + 77,8 ≈ 102 m, c’est encore pire."},
]

SERIES["Physique – Chapitre II : Travail et puissance"] = [
 {"k": "book", "src": "p. 42, ex. 1", "q": "Une voiture de 1,2 t est poussée sur une route horizontale ; sa vitesse passe de 0 à 9 km/h sur 10 m. Travail de la force résultante : 5400 J ; 37,5 J ; 3750 J ou 3,75 J ?",
  "a": "W = ΔEc = ½ × 1200 × 2,5² = 3750 J."},
 {"k": "book", "src": "p. 42, ex. 2", "q": "Un camion de 4,5 t, au repos, développe une puissance constante de 20 kW. Vitesse acquise en une minute (sans frottement) : 23 ; 35 ; 20 ou 30 m/s ?",
  "a": "½mv² = P × t ⇒ v = √(2 × 20 000 × 60/4500) ≈ 23 m/s."},
 {"k": "book", "src": "p. 42, ex. 3", "q": "Une automobile de 1100 kg roule à vitesse constante sur 2 km de route horizontale, puis monte une pente de 8 % sur 1500 m ; les frottements valent 1850 N. Travail du poids puis des frottements sur le trajet complet (g = 9,8 N/kg).",
  "a": "Poids : seule la montée compte, h = 1500 × 0,08 = 120 m ⇒ W = −mgh ≈ −1,29 × 10⁶ J.\nFrottements : W = −1850 × 3500 ≈ −6,48 × 10⁶ J."},
 {"k": "book", "src": "p. 42, ex. 4", "q": "Un pendule (boule de 50 g, fil de 30 cm) remonte de la verticale jusqu’à un angle de 30°. 1) Travail du poids. 2) Travail de la tension du fil. 3) Travail du poids sur un tour complet.",
  "a": "1) h = L(1 − cos 30°) ≈ 0,040 m ⇒ W = −mgh ≈ −0,050 × 9,8 × 0,040 ≈ −0,020 J.\n2) Nul : la tension est perpendiculaire au déplacement.\n3) Nul : le point revient à la même altitude."},
 {"k": "book", "src": "p. 42, ex. 5", "q": "Une boule de flipper de 150 g est lancée par un ressort (k = 60 N/m) comprimé de 10 cm. Travail de la tension du ressort et vitesse de la boule.",
  "a": "W = ½kx² = 0,5 × 60 × 0,01 = 0,30 J = ½mv² ⇒ v = √(0,6/0,15) = 2 m/s."},
 {"k": "book", "src": "p. 42, ex. 6, 7 et 8", "q": "1) Puissance moyenne d’une machine qui soulève 500 kg à 20 m en 60 s. 2) Puissance d’une voiture de 1000 kg montant une pente de 3 % à 20 m/s (sans frottement). 3) Puissance d’une turbine recevant 3000 kg/min d’eau tombant de 120 m, rendement 80 %. (g = 9,8 N/kg)",
  "a": "1) P = mgh/t = 500 × 9,8 × 20/60 ≈ 1,63 kW.\n2) P = mg sin α × v ≈ 1000 × 9,8 × 0,03 × 20 ≈ 5,9 kW.\n3) P = 0,8 × 50 × 9,8 × 120 ≈ 47 kW."},
 {"k": "book", "src": "p. 43, ex. 9", "q": "Une voiture de 1,5 t roule à 108 km/h sur sol horizontal ; frottements 1800 N. 1) Travail du poids et de la force motrice sur 10 km. 2) Puissance. 3) Même question sur une pente de 12 %.",
  "a": "1) Poids : 0 ; force motrice = frottements : W = 1800 × 10⁴ = 1,8 × 10⁷ J.\n2) P = Fv = 1800 × 30 = 54 kW.\n3) Il faut en plus mg sin α ≈ 1500 × 9,8 × 0,12 ≈ 1,76 × 10³ N : F ≈ 3,56 × 10³ N, P ≈ 107 kW ; le poids fournit alors un travail ≈ −1,76 × 10⁷ J sur 10 km."},
 {"k": "book", "src": "p. 43", "q": "Le frottement de l’air est proportionnel au carré de la vitesse. 1) Comparer les puissances motrices à 100 et à 130 km/h. 2) Consommation à 130 km/h si elle est de 6 L/100 km à 100 km/h.",
  "a": "1) P = f × v ∝ v³ : rapport (1,3)³ ≈ 2,2.\n2) L’énergie par km ∝ f ∝ v² : 6 × 1,3² ≈ 10,1 L/100 km."},
 {"k": "int", "src": "", "q": "Une pompe solaire doit remonter 18 m³ d’eau par jour d’un puits de 25 m de profondeur. Elle fonctionne 6 h par jour avec un rendement de 40 % (g = 10 N/kg).\n1) Travail utile fourni chaque jour.\n2) Puissance utile, puis puissance électrique nécessaire.",
  "a": "1) W = mgh = 18 000 × 10 × 25 = 4,5 × 10⁶ J.\n2) P_utile = 4,5 × 10⁶/21 600 ≈ 208 W ; P_électrique ≈ 208/0,4 ≈ 520 W."},
]

SERIES["Physique – Chapitre III : Énergie potentielle et énergie mécanique"] = [
 {"k": "book", "src": "p. 58, ex. 2", "q": "Deux objets A et B sont à la même altitude ; vA = 2vB et mB = 4mA. Laquelle des relations est vraie : Ec(A) = Ec(B) ; Ep(A) = Ep(B) ; Em(A) = Em(B) ?",
  "a": "Ec(A) = ½mA(2vB)² = 2mAvB² et Ec(B) = ½(4mA)vB² = 2mAvB² : Ec(A) = Ec(B). Les énergies potentielles diffèrent (Ep(B) = 4Ep(A)), donc les énergies mécaniques aussi."},
 {"k": "book", "src": "p. 58, ex. 4", "q": "Sidi lance verticalement vers le haut une pierre de 65 g à 5 m/s, d’un point situé 4,5 m au-dessus de l’eau (référence de Ep ; g = 9,81 N/kg ; frottements négligés). 1) Ec, Ep, Em au départ. 2) Hauteur maximale H. 3) Vitesse en entrant dans l’eau (km/h).",
  "a": "1) Ec = ½ × 0,065 × 25 ≈ 0,81 J ; Ep = 0,065 × 9,81 × 4,5 ≈ 2,87 J ; Em ≈ 3,68 J.\n2) Em se conserve ; au sommet Ec = 0 : H = Em/(mg) ≈ 5,77 m.\n3) Ep = 0 : v = √(2Em/m) ≈ 10,6 m/s ≈ 38 km/h."},
 {"k": "book", "src": "p. 59, ex. 5", "q": "Un solide de 10 g est lâché du bord A d’une demi-sphère de rayon 1,8 m et glisse jusqu’au fond B (g = 10 m/s²). 1) Vitesse en B sans frottement. 2) En réalité il arrive avec 4 m/s : intensité de la force de frottement (constante).",
  "a": "1) vB = √(2gr) = √36 = 6 m/s.\n2) Théorème de l’énergie cinétique : ½mvB² = mgr − f × (πr/2) ⇒ f = (0,18 − 0,08)/2,83 ≈ 0,035 N."},
 {"k": "book", "src": "p. 60, ex. 9 (1re phase)", "q": "Un skieur nautique de 70 kg, tracté par un câble parallèle à l’eau, part du repos et atteint 72 km/h après 200 m ; le frottement de l’eau vaut 2000 N. 1) Ec en B. 2) Force de traction moyenne. 3) Puissance moyenne si la phase dure 20 s.",
  "a": "1) Ec = ½ × 70 × 20² = 14 000 J.\n2) T × 200 − 2000 × 200 = 14 000 ⇒ T = 2070 N.\n3) P = T × 200/20 = 20,7 kW."},
 {"k": "extra", "src": "", "q": "Un ressort de raideur 200 N/m est comprimé de 5 cm. Quelle énergie potentielle élastique emmagasine-t-il ? À quelle vitesse peut-il lancer une bille de 20 g sur un plan horizontal sans frottement ?",
  "a": "Ep = ½kx² = 0,5 × 200 × 0,0025 = 0,25 J ; v = √(2Ep/m) = √25 = 5 m/s."},
 {"k": "extra", "src": "", "q": "Une bille de 50 g est lâchée sans vitesse d’une hauteur de 2 m et rebondit jusqu’à 1,5 m. Quelle énergie a été perdue lors du choc ? (g = 10 N/kg)",
  "a": "ΔEp = mg(2 − 1,5) = 0,05 × 10 × 0,5 = 0,25 J, transformés en chaleur et déformation."},
 {"k": "int", "src": "", "q": "Un wagonnet de montagnes russes (500 kg) part sans vitesse d’un sommet A à 40 m de hauteur, descend jusqu’en B (au sol) puis remonte vers un second sommet C à 30 m (g = 10 N/kg).\n1) Vitesse en B sans frottement.\n2) Vitesse en C.\n3) En réalité il arrive en C à 10 m/s : énergie perdue par frottement ?",
  "a": "1) vB = √(2 × 10 × 40) ≈ 28,3 m/s.\n2) vC = √(2 × 10 × 10) ≈ 14,1 m/s.\n3) Em(A) = 200 000 J ; Em(C) = 150 000 + ½ × 500 × 100 = 175 000 J : perte de 25 000 J."},
]

SERIES["Physique – Chapitre IV : Transferts thermiques et calorimétrie"] = [
 {"k": "book", "src": "p. 74, ex. 1", "q": "Un bloc de cuivre de 220 g reçoit 3,6 kJ ; sa température augmente de 43 °C. Capacité thermique du bloc ?",
  "a": "C = Q/Δθ = 3600/43 ≈ 83,7 J/K (capacité massique ≈ 380 J·kg⁻¹·K⁻¹)."},
 {"k": "book", "src": "p. 74, ex. 2", "q": "Un calorimètre en laiton (100 g ; c = 418 J·kg⁻¹·K⁻¹) contient 200 g d’eau et 140 g d’aluminium à 15 °C ; on ajoute 300 g d’eau à 60 °C ; θf = 40 °C. Chaleur massique de l’aluminium (c_eau = 4185 J·kg⁻¹·K⁻¹).",
  "a": "Chaleur cédée : 0,3 × 4185 × 20 = 25 110 J. Chaleur reçue : 0,1 × 418 × 25 + 0,2 × 4185 × 25 + 0,14 × c × 25. D’où c ≈ 897 J·kg⁻¹·K⁻¹."},
 {"k": "book", "src": "p. 74, ex. 3", "q": "Vase en aluminium de 50 g (c = 920), 100 g d’eau (c = 4190), accessoires 15 J/K, à 17,2 °C. On ajoute de l’eau à 100 °C ; θe = 38,5 °C. 1) Capacité thermique totale C. 2) Capacité C′ et masse de l’eau ajoutée.",
  "a": "1) C = 46 + 419 + 15 = 480 J/K.\n2) C′(100 − 38,5) = C(38,5 − 17,2) ⇒ C′ ≈ 166 J/K ⇒ m = 166/4190 ≈ 40 g."},
 {"k": "book", "src": "p. 75, ex. 4", "q": "Un verre de jus (capacité 550 J/K) est à 30 °C ; on ajoute de la glace à 0 °C pour obtenir 10 °C. Masse de glace (Lf = 3,34 × 10⁵ J/kg ; c_eau = 4185).",
  "a": "m(Lf + c_eau × 10) = 550 × 20 ⇒ m = 11 000/376 000 ≈ 29 g."},
 {"k": "book", "src": "p. 75, ex. 6", "q": "Un calorimètre (C = 120 J/K) contient 250 g d’eau et 40 g de glace en équilibre. 1) Température ? 2) Après un apport de 51 530 J, θ = 28,8 °C : chaleur latente de fusion de la glace.",
  "a": "1) 0 °C (eau et glace coexistent).\n2) 51 530 = 0,04 Lf + (120 + 0,29 × 4185) × 28,8 ⇒ Lf ≈ 3,28 × 10⁵ J/kg."},
 {"k": "book", "src": "p. 75, ex. 7", "q": "1) Combustion du propane. 2) Énergie dégagée par 10 g de propane (pouvoir calorifique (662n + 260) kJ/mol). 3) Elle chauffe 3 kg d’eau à 15 °C : température finale.",
  "a": "1) C₃H₈ + 5O₂ → 3CO₂ + 4H₂O.\n2) n = 3 : 2246 kJ/mol ; 10/44 mol ⇒ E ≈ 510 kJ.\n3) Δθ = 510 000/(3 × 4185) ≈ 40,7 °C ⇒ θ ≈ 55,7 °C."},
 {"k": "book", "src": "p. 75, ex. 9", "q": "Un bloc de plomb de 280 g à 98 °C est plongé dans un calorimètre (C = 209 J/K) contenant 350 g d’eau à 16 °C ; θe = 17,7 °C. Chaleur massique du plomb.",
  "a": "0,28 × c × (98 − 17,7) = (209 + 0,35 × 4185)(17,7 − 16) ⇒ c ≈ 127 J·kg⁻¹·K⁻¹."},
 {"k": "book", "src": "p. 75", "q": "Un morceau de fer de 500 g à −30 °C est plongé dans 200 g d’eau à 20 °C (calorimètre de capacité négligeable ; c_Fe = 460). État final ?",
  "a": "Pour amener le fer à 0 °C il faut 6900 J ; l’eau en refroidissant à 0 °C peut céder 16 740 J : il n’y a pas de glace. 0,5 × 460(θ + 30) = 0,2 × 4185(20 − θ) ⇒ θ ≈ 9,2 °C."},
 {"k": "int", "src": "", "q": "Un chauffe-eau électrique de 100 L chauffe l’eau de 15 °C à 60 °C. Sa résistance a une puissance de 2 kW.\n1) Énergie nécessaire (c = 4185 J·kg⁻¹·K⁻¹).\n2) Durée de chauffe (sans pertes).\n3) Coût si le kWh vaut 60 UM.",
  "a": "1) Q = 100 × 4185 × 45 ≈ 1,88 × 10⁷ J ≈ 5,2 kWh.\n2) t = Q/P ≈ 9400 s ≈ 2 h 37 min.\n3) 5,2 × 60 ≈ 314 UM."},
]

SERIES["Physique – Chapitre V : Champ magnétique"] = [
 {"k": "book", "src": "p. 86, ex. 1 et 2", "q": "QCM : 1) Autour d’un aimant, le champ magnétique : est nul à l’extérieur / sort du pôle nord et entre par le pôle sud / sort du pôle sud et entre par le pôle nord ? 2) L’origine principale d’un champ magnétique est : une charge au repos / le mouvement de charges (courant) / la gravitation ?",
  "a": "1) Il sort du pôle nord et entre par le pôle sud (à l’extérieur de l’aimant).\n2) Le mouvement de charges électriques (courant électrique)."},
 {"k": "book", "src": "p. 87, ex. 9", "q": "Une bobine de 20 cm comporte 2000 spires ; son axe est perpendiculaire au méridien magnétique. 1) Champ au centre pour I = 50 mA (μ₀ = 4π × 10⁻⁷ SI). 2) Position d’une petite aiguille aimantée au centre, sans courant puis avec courant (B_H = 2 × 10⁻⁵ T).",
  "a": "1) B = μ₀NI/ℓ = 4π × 10⁻⁷ × 10 000 × 0,05 ≈ 6,3 × 10⁻⁴ T, selon l’axe.\n2) Sans courant, l’aiguille suit B⃗_H (perpendiculaire à l’axe). Avec courant, elle suit B⃗ + B⃗_H : tan α = B_H/B ≈ 0,032 ⇒ elle fait un angle d’environ 1,8° avec l’axe (presque alignée sur l’axe)."},
 {"k": "book", "src": "p. 88", "q": "Une bobine de 0,5 m comporte 1000 spires, axe perpendiculaire au méridien magnétique. Avec un courant I, l’aiguille placée au centre dévie de 30°. 1) Pourquoi dévie-t-elle ? 2) Valeur de I et du champ dans la bobine. 3) Angle de déviation pour I′ = 2I. (B_H = 2 × 10⁻⁵ T)",
  "a": "1) Elle s’oriente selon la résultante de B⃗_H et du champ B⃗ de la bobine.\n2) tan 30° = B/B_H ⇒ B ≈ 1,15 × 10⁻⁵ T ; I = Bℓ/(μ₀N) ≈ 4,6 mA.\n3) tan θ = 2 tan 30° ⇒ θ ≈ 49°."},
 {"k": "book", "src": "p. 89", "q": "1) Champ au centre d’un solénoïde de 50 cm comportant 250 spires, I = 2,5 A. 2) Un solénoïde donne 5,0 mT avec 2,5 A : nombre de spires par mètre ? 3) Longueur d’un solénoïde de 1500 spires donnant 7,5 mT sous 3,0 A.",
  "a": "1) B = μ₀nI = 4π × 10⁻⁷ × 500 × 2,5 ≈ 1,57 mT.\n2) n = B/(μ₀I) ≈ 1,59 × 10³ spires/m.\n3) ℓ = μ₀NI/B ≈ 0,75 m."},
 {"k": "book", "src": "p. 89", "q": "Deux aimants perpendiculaires créent en M des champs B₁ = 4 × 10⁻³ T et B₂ = 3 × 10⁻³ T perpendiculaires. Valeur du champ résultant et angle α = (B⃗₁ ; B⃗).",
  "a": "B = √(B₁² + B₂²) = 5 × 10⁻³ T ; tan α = 3/4 ⇒ α ≈ 36,9°."},
 {"k": "book", "src": "p. 89", "q": "Un aimant crée en un point P intérieur à un solénoïde (140 spires, 16 cm) un champ de 2,5 mT. Quelle intensité faut-il pour annuler le champ en P ?",
  "a": "Il faut un champ du solénoïde de même valeur et de sens opposé : I = Bℓ/(μ₀N) = 2,5 × 10⁻³ × 0,16/(4π × 10⁻⁷ × 140) ≈ 2,3 A, dans le sens qui crée un champ opposé à celui de l’aimant."},
 {"k": "extra", "src": "", "q": "Un capteur de champ magnétique de sensibilité 20 mV/mT indique 227 mV au voisinage d’un aimant. Quelle est la valeur du champ ?",
  "a": "B = 227/20 ≈ 11,4 mT."},
 {"k": "int", "src": "", "q": "Un appareil d’IRM utilise un solénoïde supraconducteur de 2 m de long comportant 20 000 spires, qui crée un champ de 1,5 T.\n1) Calculer l’intensité du courant nécessaire.\n2) Comparer ce champ au champ magnétique terrestre (5 × 10⁻⁵ T).\n3) Pourquoi interdit-on les objets métalliques dans la salle ?",
  "a": "1) I = Bℓ/(μ₀N) = 1,5 × 2/(4π × 10⁻⁷ × 20 000) ≈ 119 A.\n2) 1,5/5 × 10⁻⁵ = 30 000 fois plus grand.\n3) Les objets en fer sont violemment attirés par un champ aussi intense et deviennent des projectiles dangereux."},
]

SERIES["Physique – Chapitre VI : Potentiel et différence de potentiel"] = [
 {"k": "book", "src": "p. 104, ex. 1", "q": "Un pendule électrostatique (q = 2 × 10⁻⁶ C ; m = 100 g ; g = 10 N/kg) est placé dans un champ horizontal E = 2 × 10⁵ V/m. Angle à l’équilibre : 30° ; 42,5° ; 21,8° ou 60° ?",
  "a": "tan α = qE/(mg) = 0,4/1 = 0,4 ⇒ α ≈ 21,8°."},
 {"k": "book", "src": "p. 104, ex. 3 et 4", "q": "1) Champ créé par un proton à 10⁻¹⁰ m. 2) Une charge crée 10 N/C à 1 cm : valeur de q ; champ à 2, 3, 4, 5 cm. (k = 9 × 10⁹ SI)",
  "a": "1) E = ke/r² = 9 × 10⁹ × 1,6 × 10⁻¹⁹/10⁻²⁰ = 1,44 × 10¹¹ V/m.\n2) q = Er²/k ≈ 1,1 × 10⁻¹³ C. E ∝ 1/r² : 2,5 ; 1,1 ; 0,63 ; 0,40 N/C."},
 {"k": "book", "src": "p. 104, ex. 6", "q": "Aux sommets A, B, C, D d’un carré de côté 5 cm on place +q, +q, +3q, +3q (q = 1,0 nC). Caractéristiques du champ au centre.",
  "a": "Distance au centre r = a/√2 ; E(q) = kq/r² = 9 × 10⁹ × 10⁻⁹/1,25 × 10⁻³ = 7200 V/m. Pour la diagonale AC : 3 × 7200 − 7200 = 14 400 V/m dirigé de C vers A ; de même 14 400 V/m de D vers B. Ces deux champs sont perpendiculaires : E ≈ 2,0 × 10⁴ V/m, perpendiculaire aux côtés AB et CD, dirigé du côté CD vers le côté AB."},
 {"k": "book", "src": "p. 104, ex. 8 et 9", "q": "1) Un proton est accéléré sous 1 MV : travail de la force électrique, énergie acquise en MeV. 2) Un électron passe de A (10 V) à B (100 V) avec vA = 10⁵ m/s : travail et vitesse en B (mₑ = 9,1 × 10⁻³¹ kg).",
  "a": "1) W = eU = 1,6 × 10⁻¹³ J (positif, la force est motrice) ; 1 MeV.\n2) W = q(VA − VB) = (−e)(−90) = 1,44 × 10⁻¹⁷ J. vB = √(vA² + 2W/m) ≈ 5,6 × 10⁶ m/s."},
 {"k": "book", "src": "p. 105", "q": "Un électron passe en A (VA = 100 V) avec la vitesse 5 × 10⁶ m/s. Potentiel VB pour qu’il arrive en B avec une vitesse nulle ? Peut-il atteindre un point C où VC = 10 V ?",
  "a": "½mvA² = (−e)(VA − VB) ⇒ VB = VA − mvA²/(2e) ≈ 100 − 71 ≈ 29 V. Il ne peut pas atteindre un point de potentiel inférieur à 29 V : il n’atteint pas C."},
 {"k": "book", "src": "p. 105", "q": "Dans un tube de Crookes, des électrons partent de la cathode sans vitesse ; UAC = 3000 V. Énergie cinétique (en eV) et vitesse à l’arrivée sur l’anode.",
  "a": "Ec = eU = 3000 eV = 4,8 × 10⁻¹⁶ J ; v = √(2Ec/m) ≈ 3,2 × 10⁷ m/s."},
 {"k": "book", "src": "p. 105", "q": "On maintient 1000 V entre deux plaques distantes de 5 cm. Une charge q = 10⁻¹² C va de A (à 1 cm de la plaque +) à B (à 2 cm de la plaque −). 1) Champ. 2) VB − VA. 3) Énergies potentielles (référence : plaque −). 4) Travail de la force électrique.",
  "a": "1) E = U/d = 2 × 10⁴ V/m.\n2) VA = 800 V, VB = 400 V : VB − VA = −400 V.\n3) Ep(A) = 8 × 10⁻¹⁰ J ; Ep(B) = 4 × 10⁻¹⁰ J.\n4) W = q(VA − VB) = 4 × 10⁻¹⁰ J."},
 {"k": "int", "src": "", "q": "Dans une ancienne télévision, les électrons sont accélérés sous 20 kV avant de frapper l’écran.\n1) Quelle énergie (en eV et en J) acquiert chaque électron ?\n2) Le faisceau transporte 0,5 mA : combien d’électrons frappent l’écran par seconde ? Quelle puissance reçoit l’écran ?",
  "a": "1) 20 keV = 3,2 × 10⁻¹⁵ J.\n2) N = I/e = 3,1 × 10¹⁵ électrons/s ; P = UI = 20 000 × 5 × 10⁻⁴ = 10 W."},
]

SERIES["Physique – Chapitre VII : Puissance électrique dans une portion de circuit"] = [
 {"k": "book", "src": "p. 121, ex. 3", "q": "Un générateur (E = 6 V ; r = 4 Ω) alimente un résistor de 50 Ω. Point de fonctionnement et puissance dissipée dans le résistor.",
  "a": "I = E/(R + r) = 6/54 ≈ 0,111 A ; U = RI ≈ 5,56 V ; P = RI² ≈ 0,62 W."},
 {"k": "book", "src": "p. 121, ex. 4", "q": "Un four à micro-ondes de 1200 W a un rendement de 65 % ; il faut 4,18 J pour chauffer 1 mL d’eau de 1 °C. 1) Énergie perdue en 2 min. 2) Durée minimale pour faire bouillir 500 mL d’eau à 20 °C.",
  "a": "1) 0,35 × 1200 × 120 = 50 400 J.\n2) Q = 500 × 4,18 × 80 = 167 200 J ; puissance utile 780 W ⇒ t ≈ 214 s (environ 3 min 34 s)."},
 {"k": "book", "src": "p. 122, ex. 7", "q": "Une batterie (E = 12 V ; r = 0,12 Ω ; 35 A·h) alimente une veilleuse (5 W ; 12 V) (Correction : le manuel écrit « 5 Ω » et donne I = 4,15 A au lieu de 0,415 A). 1) Résistance de la lampe et intensité. 2) Durée d’éclairage. 3) En charge sous U′ = 13,9 V avec E′ = 13,2 V : intensité et puissance consommée.",
  "a": "1) R = U²/P = 28,8 Ω ; I = 12/(28,8 + 0,12) ≈ 0,415 A.\n2) t = 35/0,415 ≈ 84 h.\n3) I′ = (13,9 − 13,2)/0,12 ≈ 5,8 A ; P′ = 13,9 × 5,8 ≈ 81 W."},
 {"k": "book", "src": "p. 122, ex. 8", "q": "Un générateur (E = 6 V ; r = 1 Ω) alimente un moteur (E′ = 4 V ; r′ = 2 Ω). 1) Intensité. 2) Si on bloque le moteur. 3) En court-circuit du générateur.",
  "a": "1) I = (E − E′)/(r + r′) = 2/3 ≈ 0,67 A.\n2) Moteur bloqué (E′ = 0) : I = 6/3 = 2 A.\n3) Icc = E/r = 6 A."},
 {"k": "book", "src": "p. 122, ex. 9", "q": "Dans un électrolyseur isolé thermiquement, la température s’élève de 1,5 °C en 10 min (capacité 500 J/K) ; I = 1 A. 1) Puissance Joule. 2) Résistance interne. 3) F.c.é.m. si son rendement est 80 %. 4) Le rendement global est 0,56 : f.é.m. et résistance interne du générateur.",
  "a": "1) P = 500 × 1,5/600 = 1,25 W.\n2) r′ = P/I² = 1,25 Ω.\n3) E′/(E′ + r′I) = 0,8 ⇒ E′ = 5 V (U = 6,25 V).\n4) E′/E = 0,56 ⇒ E ≈ 8,9 V ; r = (E − U)/I ≈ 2,7 Ω."},
 {"k": "book", "src": "p. 123", "q": "Une batterie (12 V ; 1 Ω), un moteur (E′ ; r′) et un résistor de 3,2 Ω sont en série. Moteur bloqué : 2,5 A ; moteur libre : 0,6 A. 1) E′ et r′. 2) Rendements de la batterie, du moteur et du circuit. 3) Le moteur monte une masse de 200 g sur une pente de 30° (transmission 60 %) : vitesse ? (g = 9,8 N/kg)",
  "a": "1) Bloqué : 12 = (1 + 3,2 + r′) × 2,5 ⇒ r′ = 0,6 Ω. Libre : 12 − E′ = 4,8 × 0,6 ⇒ E′ = 9,12 V.\n2) Batterie : (12 − 0,6)/12 = 95 % ; moteur : 9,12/(9,12 + 0,36) ≈ 96 % ; ensemble : 9,12/12 = 76 %.\n3) P_utile = 0,6 × 9,12 × 0,6 ≈ 3,28 W = mg sin 30° × v = 0,98v ⇒ v ≈ 3,3 m/s."},
 {"k": "int", "src": "", "q": "Une famille utilise chaque jour : 6 lampes de 15 W pendant 5 h, un réfrigérateur de 150 W fonctionnant 10 h et un téléviseur de 100 W pendant 4 h.\n1) Énergie consommée par jour (en kWh).\n2) Coût mensuel (30 jours) si le kWh coûte 60 UM.\n3) Quelle économie si on remplace les lampes par des lampes de 7 W ?",
  "a": "1) 0,45 + 1,5 + 0,4 = 2,35 kWh.\n2) 2,35 × 30 × 60 = 4230 UM.\n3) Lampes : 6 × 8 W × 5 h = 0,24 kWh/jour en moins, soit 0,24 × 30 × 60 = 432 UM par mois."},
]

SERIES["Physique – Chapitre VIII : Le condensateur"] = [
 {"k": "book", "src": "p. 135, ex. 2", "q": "1) L’espace entre les armatures est conducteur, isolant ou semi-conducteur ? 3) C₁ = 47 μF et C₂ = 100 μF en série : UC₁ > UC₂, UC₁ < UC₂ ou égales ? 4) Sous 10 V, la charge est 10⁻⁵ C : capacité ? 6) C = 4700 μF chargé par I = 0,5 mA pendant 1 min : tension ? 7) Énergie de 330 nF sous 10 V ? 8) Durée pour charger 470 μF à 5 V avec 0,1 mA ?",
  "a": "1) Isolant (diélectrique).\n3) En série les charges sont égales, U = q/C : UC₁ > UC₂.\n4) C = q/U = 1 μF.\n6) U = It/C = 0,03/4,7 × 10⁻³ ≈ 6,38 V.\n7) W = ½CU² = 1,65 × 10⁻⁵ J.\n8) t = CU/I = 23,5 s."},
 {"k": "book", "src": "p. 136, ex. 7", "q": "Un condensateur de 1 F a un diélectrique d’épaisseur 0,1 mm et de permittivité relative 5. Surface des armatures ? (ε₀ = 8,85 × 10⁻¹² SI)",
  "a": "C = ε₀εᵣS/e ⇒ S = Ce/(ε₀εᵣ) = 10⁻⁴/(4,4 × 10⁻¹¹) ≈ 2,3 × 10⁶ m² (plus de 2 km²) : un condensateur plan de 1 F serait gigantesque, on utilise d’autres technologies."},
 {"k": "book", "src": "p. 137", "q": "L’énergie d’un condensateur chargé est 1 × 10⁻⁵ J sous 50 V. Capacité et charge.",
  "a": "C = 2W/U² = 8 × 10⁻⁹ F = 8 nF ; Q = CU = 4 × 10⁻⁷ C."},
 {"k": "extra", "src": "", "q": "Trois condensateurs de 10 μF, 20 μF et 30 μF : capacité équivalente en parallèle et en série.",
  "a": "Parallèle : 60 μF. Série : 1/C = 1/10 + 1/20 + 1/30 = 11/60 ⇒ C ≈ 5,45 μF."},
 {"k": "extra", "src": "", "q": "Un condensateur C₁ = 2 μF est chargé sous 100 V puis relié à un condensateur C₂ = 3 μF déchargé. Tension finale et énergies avant et après. Commenter.",
  "a": "Q = 2 × 10⁻⁴ C se répartit : U = Q/(C₁ + C₂) = 40 V. Avant : ½ × 2 × 10⁻⁶ × 10⁴ = 0,01 J ; après : ½ × 5 × 10⁻⁶ × 1600 = 0,004 J. 60 % de l’énergie est perdue (effet Joule dans les fils, rayonnement)."},
 {"k": "int", "src": "", "q": "Le flash d’un appareil photo utilise un condensateur de 150 μF chargé sous 300 V, qui se décharge en 1 ms dans la lampe.\n1) Énergie emmagasinée.\n2) Puissance moyenne de l’éclair.\n3) Pourquoi ne pas brancher directement la lampe sur la pile de 3 V ?",
  "a": "1) W = ½CU² = 0,5 × 150 × 10⁻⁶ × 9 × 10⁴ = 6,75 J.\n2) P = 6,75/10⁻³ = 6750 W.\n3) La pile ne peut pas fournir une telle puissance : le condensateur accumule lentement l’énergie et la restitue en un temps très court."},
]

SERIES["Physique – Chapitre IX : Courant alternatif, oscilloscope et transformateur"] = [
 {"k": "book", "src": "p. 154, ex. 1", "q": "Le courant alternatif est caractérisé par : une intensité qui circule toujours dans le même sens / qui varie périodiquement en sens et en valeur / constante / qui circule seulement dans les métaux ?",
  "a": "Une intensité qui varie périodiquement en sens et en valeur."},
 {"k": "book", "src": "p. 154, ex. 2", "q": "Une lampe est alimentée en alternatif sinusoïdal. Le voltmètre indique 12 V et l’ampèremètre 0,5 A. 1) Que représente 12 V ? 2) Tension maximale. 3) Résistance de la lampe.",
  "a": "1) La tension efficace.\n2) Umax = 12√2 ≈ 17 V.\n3) R = Ueff/Ieff = 24 Ω."},
 {"k": "book", "src": "p. 154, ex. 3", "q": "Tension sinusoïdale de fréquence 100 Hz et de valeur efficace 1,44 V. a) Période. b) Umax. c) Vitesse de balayage si une période occupe 10 divisions. d) Sensibilité verticale si Umax occupe 2 divisions.",
  "a": "a) T = 1/f = 10 ms.\nb) Umax = 1,44√2 ≈ 2,04 V.\nc) B = 10 ms/10 div = 1 ms/div.\nd) Sv ≈ 2,04/2 ≈ 1 V/div."},
 {"k": "extra", "src": "", "q": "Sur un oscilloscope (2 V/div ; 5 ms/div), une tension sinusoïdale a une amplitude de 3,4 divisions et une période de 4 divisions. Calculer Umax, Ueff, T et f.",
  "a": "Umax = 6,8 V ; Ueff = 6,8/√2 ≈ 4,8 V ; T = 20 ms ; f = 50 Hz."},
 {"k": "extra", "src": "", "q": "Un transformateur a 1100 spires au primaire et 60 spires au secondaire ; il est branché sur le secteur (220 V). Tension au secondaire ? Rapport de transformation ? Abaisseur ou élévateur ?",
  "a": "U₂ = U₁ × N₂/N₁ = 220 × 60/1100 = 12 V ; m = N₂/N₁ ≈ 0,055 : transformateur abaisseur."},
 {"k": "extra", "src": "", "q": "Un fer à repasser (résistance) consomme 1000 W sous 220 V efficaces. Intensité efficace et intensité maximale.",
  "a": "Ieff = P/Ueff ≈ 4,55 A ; Imax = Ieff√2 ≈ 6,4 A."},
 {"k": "int", "src": "", "q": "Une centrale produit une puissance de 10 MW transportée sur une ligne de résistance 10 Ω.\n1) Calculer les pertes par effet Joule si la ligne est sous 20 kV, puis sous 200 kV.\n2) Expliquer l’intérêt des transformateurs dans le transport de l’électricité.",
  "a": "1) I = P/U : 500 A sous 20 kV ⇒ pertes RI² = 2,5 MW (25 %) ; 50 A sous 200 kV ⇒ 25 kW (0,25 %).\n2) Les transformateurs élèvent la tension pour le transport (pertes réduites) puis l’abaissent pour l’utilisation (sécurité)."},
]
